data.query:
query user($where:UserWhereInput){
  user (where:$where) {
    edges {
      node {
        id
        email
      }
    }
  }
}

query productionSetup($wherePS: ProductionSetupOutputWhereInput, $whereO: ProductionSetupOperatorWhereInput){
  productionSetupOutput (where: $wherePS) {
    edges {
      node {
        id
        workunit{
          productionSetupOperators{
            edges{
              node{
                userId
              }
            }
          }
        }
      }
    }
  }
  productionSetupOperator(where:$whereO) {
    edges {
      node {
        id
        workunit {id code}

      }
    }
  }
}

branches.transform:
(
  $usage := $state.context.REQUEST.DATA.input.usage;
  $setupMaterial := productionSetupMaterial.edges.node;
  $producedQuantity := $state.context.REQUEST.DATA.output.producedQuantity;
  $usage.(
    $productId := componentProductId;
    $materialQty := $sum($setupMaterial[productId = $productId].quantity);
    allowOverConsumption ? false 
    : consumptionType.id = "actual" ? qty > $materialQty
    : consumptionType.id = "standard" ? (standardUsage * $producedQuantity) > $materialQty
  ) ~> $reduce(function ($i, $j){$i or $j})


)

data.query:
query ProductionSetupMaterial($where: ProductionSetupMaterialWhereInput, $orderBy: [ProductionSetupMaterialOrderByInput!], $first: Int, $after: String) {
  productionSetupMaterial(
    where: $where
    orderBy: $orderBy
    first: $first
    after: $after
  ) {
    edges {
      node {
        id
        priority
        quantity
        serial
        productId
      }
    }
  }
}

data.transform:
(
	$request := $state.context.REQUEST.DATA;
	$setupMaterial := productionSetupMaterial.edges.node;
	$producedQuantity := $request.output.producedQuantity;
	$scrappedQuantity := $request.output.scrappedQuantity;
	$suspectQuantity := $request.output.suspectQuantity;
	$transferSerial := null;
	$option := $state.context.REQUEST.OCustomer-DON;
	$usage := $request.input.usage;
	$materialsToConsume := $usage.(
			$productId := componentProductId;
			$materials := $setupMaterial[productId = $productId];
			$actualUsage := qty;
			$standardUsage := standardUsage;
			consumptionType.id = "actual"
				? $reduce( $materials, function( $acc, $material, $index) {
						(
							$remainingQuantity := $acc.remaining;
							$isLastMaterial := $index = $count($materials) - 1;
							$depletion := $remainingQuantity > 0? (
								$isLastMaterial?  
									$remainingQuantity : 
									($remainingQuantity > $material.quantity? $material.quantity: $remainingQuantity)
							)
							: 
							0;
							{
								"materials": $append(
									$acc.materials,
									$merge([$material, { "quantity": $depletion, "setupMaterialId": $material.id }])
								),
								"remaining": $remainingQuantity - $depletion
							}
						)
					},
					{
						"materials": [],
						"remaining": $actualUsage
					}
				)
					.materials
				: consumptionType.id = "standard"
					? $reduce( $materials, function( $acc, $material, $index) {
							(
								$remainingQuantity := $acc.remaining;
								$isLastMaterial := $index = $count($materials) - 1;
								$depletion := $remainingQuantity > 0
									? ($isLastMaterial
										? $remainingQuantity
										: ($remainingQuantity > $material.quantity
											? $material.quantity
											: $remainingQuantity))
									: 0;
								{
									"materials": $append(
										$acc.materials,
										$merge([$material, { "quantity": $depletion, "setupMaterialId": $material.id }])
									),
									"remaining": $remainingQuantity - $depletion
								}
							)
						},
						{
							"materials": [],
							"remaining": $producedQuantity * $standardUsage
						}
					)
						.materials
		);
	/* : $not(allowOverConsumption) and consumptionType.id = "actual" ? $reduce( $materials,
      function($acc, $material){
        (
          $remainingQuantity := $coalesce([$acc.remaining, $producedQuantity]);
          $depletion := $remainingQuantity > 0 ? 
            ($remainingQuantity > $material.quantity ? $material.quantity : $remainingQuantity) : 0;
          
          {
            "materials": $append($acc.materials, $merge([$material, {"quantity":  $depletion}])),
            "remaining": $remainingQuantity - $depletion
          }
        )
        
      },
      {"materials": [], "remaining": $actualUsage}
    )
    : $not(allowOverConsumption) and consumptionType.id = "standard" ? $reduce( $materials,
      function($acc, $material){
        (
          $remainingQuantity := $coalesce([$acc.remaining, $producedQuantity]);
          $depletion := $remainingQuantity > 0 ? 
            ($remainingQuantity > $material.quantity ? $material.quantity : $remainingQuantity) : 0;
          
          {
            "materials": $append($acc.materials, $merge([$material, {"quantity":  $depletion}])),
            "remaining": $remainingQuantity - $depletion
          }
        )
        
      },
      {"materials": [], "remaining": $producedQuantity * $standardUsage}
    ) */
	{
		"ACTION": "PRODUCE",
		"REQUEST": {
			"DATA": {
				"productionSetupOutputId": $state.context.REQUEST.DATA.productionSetupOutputId,
				"output": {
					"producedQuantity": $producedQuantity,
					"scrappedQuantity": $scrappedQuantity,
					"suspectQuantity": $suspectQuantity,
					"serialNumber": { "outputSerialNumber": $transferSerial }
				},
				"inputs": $materialsToConsume[quantity > 0]
			}
		}
	}
)

